#include "independent_paths.hpp"
struct Full{I h,s,e,L,R,d,b;};
Full full_profile(const G&a){valid(a);int n=a.size(),N=1<<n,F=N-1;std::vector<I>H(N),end(N),start(N);H[0]=1;auto dfs=[&](auto&&self,int first,int last,unsigned used)->void{++H[used];if(first==0)++start[used];if(last==0)++end[used];unsigned next=a[last]&~used;while(next){unsigned bit=next&-next;next-=bit;self(self,first,__builtin_ctz(bit),used|bit);}};for(int v=0;v<n;++v)dfs(dfs,v,v,1u<<v);I L=0,R=0,b=0;for(int S=0;S<N;++S){L+=end[S]*H[F^S];R+=start[S]*H[F^S];if(!(S&1))b+=H[S]*H[(F^1)^S];}return{H[F],start[F],end[F],L,R,H[F^1],b};}
G reroot(const G&a,int r){std::vector<int>v{r};for(int i=0;i<(int)a.size();++i)if(i!=r)v.push_back(i);G b(a.size());for(int i=0;i<(int)v.size();++i)for(int j=0;j<(int)v.size();++j)if(a[v[i]]>>v[j]&1)b[i]|=1u<<j;return b;}
G pad(G a,bool z){int n=a.size();for(auto&x:a)x|=1u<<n;a.push_back(0);if(z){a[0]^=1u<<n;a[n]|=1;}return a;}
I gg(int u){I ans=1;while(u>1){if(u%2){u=(u+1)/2;ans+=u-u%2;}else u/=2;}return ans;}
int main(){std::vector<G>graphs={{2,12,17,101,75,23,167,63},{2,12,17,165,43,71,31,119},{2,44,49,133,11,89,31,119},{2,52,25,35,105,197,15,95},{2,148,97,7,45,75,27,125},{2,148,41,67,45,75,23,125},{4,9,50,85,163,75,151,47},{4,9,50,85,99,139,167,31}};std::vector<int>roots{2,2,1,1,0,0,2,2},j{3,3,4,3,4,3,5,5};std::vector<std::array<I,4>>rows{{677,27,1061,49},{759,29,927,29},{1547,101,1691,109},{821,33,1079,33}};std::map<std::tuple<int,int,int>,std::array<I,4>>paired;int checks=0,readouts=0,comparisons=0;for(int source=0;source<8;++source){auto row=rows[source/2];auto walk=[&](auto&&self,const G&a,int depth,int k,int reversed)->void{auto p=full_profile(a);int u=k+1;I X=row[0]-row[2]+(row[2]-row[3])*u+row[3]*gg(u)+(row[3]-row[1])*(1-u%2);need(p.h+p.L-p.s+2*j[source]==X,"physical formula X");I expected_e=depth?row[3]*((k>>(depth-1))&1):row[1];I expected_V=(I(1)<<depth)*row[2]-row[3]*reversed;need(p.e==expected_e&&p.R+p.b==expected_V&&p.d==row[3],"physical full row");need(p.s==I(1+source%2+3*j[source]),"fixed physical starts");std::array<I,4>actual{X,p.e,p.R+p.b,p.d};auto key=std::make_tuple(source/2,depth,k);if(source%2){need(paired.at(key)==actual,"same physical paired row");++comparisons;}else paired[key]=actual;++checks;if(depth<=1){G child=readout(a);need(hp(child,100000000)==3*X+2*(1+source%2),"physical target readout");++readouts;}if(depth<3){self(self,pad(a,false),depth+1,k,2*reversed);self(self,pad(a,true),depth+1,k+(1<<depth),2*reversed+1);}};walk(walk,reroot(graphs[source],roots[source]),0,0,0);}
std::cout<<"{\"status\":\"PASS\",\"literal_source_graphs\":"<<checks<<",\"paired_row_comparisons\":"<<comparisons<<",\"literal_target_graphs\":"<<readouts<<",\"maximum_source_order\":11,\"maximum_target_order\":12,\"word_length\":3}\n";}
